// packages/renderer/src/lib/ipc.ts
export async function pickFile(options?: {
  title?: string
  defaultPath?: string
  filters?: Array<{ name: string; extensions: string[] }>
}): Promise<{ canceled: boolean; path: string | null }>
// 降级：if (!api?.pickFile) return { canceled: true, path: null }
// 透传：return api.pickFile(options)
// preload 侧（已存在）: ipcRenderer.invoke('pick-file', options) → main dialog.showOpenDialog

// useCommandPopoverTrigger.onAddSelect(type: 'attach'|'image'|'slash'): Promise<void>
// attach: r=await pickFile() → r.canceled||!r.path ? return : inputRef.insertTextAtCursor(r.path)
// image:  r=await pickFile({filters:[{name:'Images',extensions:['png','jpg','jpeg','gif','webp','bmp','svg']}]}) → r.canceled||!r.path ? return : inputRef.insertImageBadge(r.path, basename)
// slash:  saveSelection+focus+cmdType='slash'+cmdOpen=true（不变）
// try/catch 包裹 pickFile（失败静默 return）

// composer-box @dragover.prevent → isDragOver=true
// @dragleave → relatedTarget contains 检查 → 离开 box 才 isDragOver=false
// @drop.prevent → files=Array.from(dataTransfer.files)；image/* 每项：
//   insertImageBadge(placeholderMark,'拖入中…') → await handleImagePaste(file,{metaKey:true})
//   kind:'badge' → 回填 dataset.chipPath/chipName + label（或重插）；kind:'text' → 移除占位+insertText
//   末尾 isDragOver=false + refreshAttachedItems()
// boxClass 追加 isDragOver && 'border-[var(--accent)] shadow-[0_0_0_3px_rgba(79,142,247,0.25)]'
